# INC-5521: Oversold stock and stuck holds during the September flash sale

Reported by the checkout team after the 2026-09-12 flash sale.

## What we saw

- The `sneaker-limited` drop had 250 units. We confirmed 263 orders, and 13
  customers had to be refunded.
- The stock dashboard showed `reserved` going negative for two SKUs after the
  sale, and it has not recovered.
- Some customers who retried checkout after a timeout had units held twice for
  one order; the second hold only disappeared when the reservation expired.
- One order was rejected because a bundle item was out of stock, but the other
  item in the bundle stayed held until we restarted the worker pool.
- Finance reports `sold` counts that are higher than the number of orders we
  shipped for a few SKUs.

## Context

Every checkout worker calls `InventoryService` concurrently. During the sale
we ran 40 workers. The nightly `expire()` job ran once during the sale.

The unit tests all pass, and none of this reproduces when we click through
checkout by hand.

A service-wide lock (INC-5490) stopped the overselling in staging but cut
checkout throughput by 90% and was rolled back the same day.
'use strict';

class InventoryError extends Error {
  constructor(message, code) {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
  }
}

class ValidationError extends InventoryError {
  constructor(message) {
    super(message, 'VALIDATION');
  }
}

class UnknownSkuError extends InventoryError {
  constructor(sku) {
    super(`unknown sku: ${sku}`, 'UNKNOWN_SKU');
    this.sku = sku;
  }
}

class UnknownOrderError extends InventoryError {
  constructor(orderId) {
    super(`unknown order: ${orderId}`, 'UNKNOWN_ORDER');
    this.orderId = orderId;
  }
}

class InsufficientStockError extends InventoryError {
  constructor(sku, requested, available) {
    super(`insufficient stock for ${sku}: requested ${requested}, available ${available}`, 'INSUFFICIENT_STOCK');
    this.sku = sku;
    this.requested = requested;
    this.available = available;
  }
}

class OrderStateError extends InventoryError {
  constructor(orderId, status, action) {
    super(`cannot ${action} order ${orderId}: it is ${status}`, 'ORDER_STATE');
    this.orderId = orderId;
    this.status = status;
  }
}

module.exports = {
  InventoryError,
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError,
  OrderStateError
};
'use strict';

module.exports = {
  ...require('./inventory'),
  ...require('./errors'),
  ...require('./store')
};
'use strict';

const { Store } = require('./store');
const { KeyedLock } = require('./lock');
const {
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError,
  OrderStateError
} = require('./errors');

const DEFAULT_TTL_MS = 15 * 60 * 1000;
const ORDER_PREFIX = 'order:';

// The locks guard store keys, so services built on the same store share them.
const storeLocks = new WeakMap();

function locksFor(store) {
  let locks = storeLocks.get(store);
  if (!locks) {
    locks = new KeyedLock();
    storeLocks.set(store, locks);
  }
  return locks;
}

/**
 * Stock reservations for checkout.
 *
 * Every SKU has three counters: `stock` (units on hand), `reserved` (units
 * held for orders that have not been committed) and `sold`. Available stock
 * is `stock - reserved` and must never go below zero.
 *
 * An order moves reserved -> committed, or reserved -> released. Committing
 * turns its held units into sold units; releasing returns them.
 *
 * The service is called concurrently by every checkout worker. The store only
 * offers get and set, so each read-modify-write runs under a lock on the keys
 * it touches: the order first, then its SKUs in sorted order. Calls that share
 * no SKU and no order never wait for each other.
 */
class InventoryService {
  #locks;

  constructor({ store = new Store(), reservationTtlMs = DEFAULT_TTL_MS, now = () => Date.now() } = {}) {
    this.store = store;
    this.ttl = reservationTtlMs;
    this.now = now;
    this.#locks = locksFor(store);
  }

  /** Add units to a SKU, creating it if needed. Returns the SKU snapshot. */
  async addStock(sku, qty) {
    assertSku(sku);
    assertQty(qty);
    return this.#withSkus([sku], async () => {
      const item = (await this.store.get(skuKey(sku))) || { stock: 0, reserved: 0, sold: 0 };
      item.stock += qty;
      await this.store.set(skuKey(sku), item);
      return { sku, ...item };
    });
  }

  /** Units that can still be reserved. */
  async available(sku) {
    const item = await this.getItem(sku);
    return item.stock - item.reserved;
  }

  /** The SKU's counters. */
  async snapshot(sku) {
    const item = await this.getItem(sku);
    return { sku, stock: item.stock, reserved: item.reserved, sold: item.sold };
  }

  /**
   * Hold stock for an order: all of its items, or none of them.
   *
   * Idempotent by orderId: checkout retries a timed-out request with the same
   * orderId, and a retry must return the existing reservation rather than
   * hold the stock twice.
   *
   * Rejects with InsufficientStockError when any item cannot be held, and
   * then holds nothing.
   */
  async reserve(orderId, items) {
    assertOrderId(orderId);
    assertItems(items);
    const lines = items.map(({ sku, qty }) => ({ sku, qty }));
    return this.#withOrder(orderId, async () => {
      const existing = await this.store.get(orderKey(orderId));
      if (existing) {
        return toReservation(existing);
      }
      await this.#withSkus(lines.map(({ sku }) => sku), async () => {
        // Check every line before writing any, so a short or unknown SKU
        // leaves the others untouched.
        const held = [];
        for (const { sku, qty } of lines) {
          const item = await this.getItem(sku);
          const free = item.stock - item.reserved;
          if (free < qty) {
            throw new InsufficientStockError(sku, qty, free);
          }
          held.push({ sku, item: { ...item, reserved: item.reserved + qty } });
        }
        for (const { sku, item } of held) {
          await this.store.set(skuKey(sku), item);
        }
      });
      const order = { orderId, items: lines, status: 'reserved', createdAt: this.now() };
      await this.store.set(orderKey(orderId), order);
      return toReservation(order);
    });
  }

  /**
   * Turn a reservation into a sale. Idempotent: committing a committed order
   * returns it unchanged. A released order cannot be committed.
   */
  async commit(orderId) {
    assertOrderId(orderId);
    return this.#withOrder(orderId, async () => {
      const order = await this.getOrder(orderId);
      if (order.status === 'committed') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'commit');
      }
      await this.#closeOrder(order, 'committed');
      return toReservation(order);
    });
  }

  /**
   * Cancel a reservation and return its units. Idempotent: releasing a
   * released order returns it unchanged. A committed order cannot be
   * released; its units have been sold.
   */
  async release(orderId) {
    assertOrderId(orderId);
    return this.#withOrder(orderId, async () => {
      const order = await this.getOrder(orderId);
      if (order.status === 'released') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'release');
      }
      await this.#closeOrder(order, 'released');
      return toReservation(order);
    });
  }

  /**
   * Release every reservation older than the TTL that has not been committed
   * or released. Returns the orderIds it released.
   */
  async expire() {
    const cutoff = this.now() - this.ttl;
    const released = [];
    // One order at a time, each under its own lock, so the job never holds
    // up checkout calls for other orders.
    for (const key of await this.store.keys(ORDER_PREFIX)) {
      const orderId = key.slice(ORDER_PREFIX.length);
      const expired = await this.#withOrder(orderId, async () => {
        // Re-read under the lock: the order may have been committed or
        // released since keys() listed it.
        const order = await this.store.get(key);
        if (order.status === 'reserved' && order.createdAt < cutoff) {
          await this.#closeOrder(order, 'released');
          return true;
        }
        return false;
      });
      if (expired) {
        released.push(orderId);
      }
    }
    return released;
  }

  // Moves a reserved order to `status` and takes its units out of `reserved`;
  // committing also moves them from `stock` to `sold`. The caller must hold
  // the order's lock and have checked that it is still reserved.
  async #closeOrder(order, status) {
    await this.#withSkus(order.items.map(({ sku }) => sku), async () => {
      for (const { sku, qty } of order.items) {
        const item = await this.getItem(sku);
        item.reserved -= qty;
        if (status === 'committed') {
          item.stock -= qty;
          item.sold += qty;
        }
        await this.store.set(skuKey(sku), item);
      }
    });
    order.status = status;
    await this.store.set(orderKey(order.orderId), order);
  }

  #withOrder(orderId, fn) {
    return this.#locks.run([orderKey(orderId)], fn);
  }

  #withSkus(skus, fn) {
    return this.#locks.run(skus.map(skuKey), fn);
  }

  async getItem(sku) {
    assertSku(sku);
    const item = await this.store.get(skuKey(sku));
    if (!item) {
      throw new UnknownSkuError(sku);
    }
    return item;
  }

  async getOrder(orderId) {
    assertOrderId(orderId);
    const order = await this.store.get(orderKey(orderId));
    if (!order) {
      throw new UnknownOrderError(orderId);
    }
    return order;
  }
}

function skuKey(sku) {
  return `sku:${sku}`;
}

function orderKey(orderId) {
  return `${ORDER_PREFIX}${orderId}`;
}

function toReservation(order) {
  return { orderId: order.orderId, status: order.status, items: order.items.map(({ sku, qty }) => ({ sku, qty })) };
}

function assertSku(sku) {
  if (typeof sku !== 'string' || sku.trim() === '') {
    throw new ValidationError('sku must be a non-empty string');
  }
}

function assertOrderId(orderId) {
  if (typeof orderId !== 'string' || orderId.trim() === '') {
    throw new ValidationError('orderId must be a non-empty string');
  }
}

function assertQty(qty) {
  if (!Number.isInteger(qty) || qty <= 0) {
    throw new ValidationError('qty must be a positive integer');
  }
}

function assertItems(items) {
  if (!Array.isArray(items) || items.length === 0) {
    throw new ValidationError('items must be a non-empty array');
  }
  const seen = new Set();
  for (const entry of items) {
    if (!entry || typeof entry !== 'object') {
      throw new ValidationError('each item must be an object with sku and qty');
    }
    assertSku(entry.sku);
    assertQty(entry.qty);
    if (seen.has(entry.sku)) {
      throw new ValidationError(`duplicate sku in items: ${entry.sku}`);
    }
    seen.add(entry.sku);
  }
}

module.exports = { InventoryService, DEFAULT_TTL_MS };
'use strict';

/**
 * In-process mutual exclusion per key. Callers of the same key run one at a
 * time in arrival order; callers with no key in common never wait for each
 * other. A key's entry is dropped once nobody holds or waits for it, so the
 * map only grows with the keys in use at that moment.
 */
class KeyedLock {
  constructor() {
    // key -> resolvers of callers waiting behind the current holder
    this.waiters = new Map();
  }

  /**
   * Run `fn` while holding every key in `keys`, and return its result. Keys
   * are taken in sorted order, so two calls that need overlapping keys cannot
   * deadlock. The keys are released when `fn` settles, whether it resolves
   * or rejects.
   */
  async run(keys, fn) {
    const ordered = [...new Set(keys)].sort();
    // Sequential on purpose: taking keys in one global order is what rules
    // out deadlock.
    for (const key of ordered) {
      await this.acquire(key);
    }
    try {
      return await fn();
    } finally {
      for (const key of ordered) {
        this.release(key);
      }
    }
  }

  acquire(key) {
    const queue = this.waiters.get(key);
    if (!queue) {
      this.waiters.set(key, []);
      return Promise.resolve();
    }
    return new Promise(resolve => queue.push(resolve));
  }

  release(key) {
    const next = this.waiters.get(key).shift();
    if (next) {
      next();
    } else {
      this.waiters.delete(key);
    }
  }
}

module.exports = { KeyedLock };
'use strict';

// In-memory key-value store with the latency profile of the Redis cluster
// used in production: every call yields to the event loop before it reads or
// writes, so concurrent callers interleave the way they do against the real
// store. Values are copied on the way in and out.
class Store {
  constructor() {
    this.data = new Map();
  }

  async get(key) {
    await tick();
    const value = this.data.get(key);
    return value === undefined ? undefined : structuredClone(value);
  }

  async set(key, value) {
    await tick();
    this.data.set(key, structuredClone(value));
  }

  async keys(prefix) {
    await tick();
    return [...this.data.keys()].filter(key => key.startsWith(prefix));
  }
}

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

module.exports = { Store };
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  InsufficientStockError,
  UnknownSkuError,
  UnknownOrderError,
  ValidationError,
  OrderStateError
} = require('../src');

async function service(stock = { widget: 10 }) {
  const svc = new InventoryService();
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

test('addStock creates and tops up a sku', async () => {
  const svc = new InventoryService();
  assert.deepEqual(await svc.addStock('widget', 5), { sku: 'widget', stock: 5, reserved: 0, sold: 0 });
  assert.deepEqual(await svc.addStock('widget', 2), { sku: 'widget', stock: 7, reserved: 0, sold: 0 });
});

test('reserve holds stock and commit sells it', async () => {
  const svc = await service();
  const reservation = await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
  assert.deepEqual(reservation, { orderId: 'o1', status: 'reserved', items: [{ sku: 'widget', qty: 3 }] });
  assert.equal(await svc.available('widget'), 7);
  await svc.commit('o1');
  assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 7, reserved: 0, sold: 3 });
});

test('release returns held stock', async () => {
  const svc = await service();
  await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
  const released = await svc.release('o1');
  assert.equal(released.status, 'released');
  assert.equal(await svc.available('widget'), 10);
});

test('reserve does not modify the caller\'s items', async () => {
  const svc = await service();
  const items = Object.freeze([Object.freeze({ sku: 'widget', qty: 2 })]);
  const reservation = await svc.reserve('o1', items);
  assert.notEqual(reservation.items, items);
  assert.deepEqual(items, [{ sku: 'widget', qty: 2 }]);
});

test('reserve is idempotent for a retried order', async () => {
  const svc = await service();
  await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
  await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
  assert.equal(await svc.available('widget'), 8);
});

test('reserve rejects when stock is short', async () => {
  const svc = await service({ widget: 1 });
  await assert.rejects(svc.reserve('o1', [{ sku: 'widget', qty: 2 }]), InsufficientStockError);
});

test('unknown skus and bad input are rejected', async () => {
  const svc = await service();
  await assert.rejects(svc.reserve('o1', [{ sku: 'nope', qty: 1 }]), UnknownSkuError);
  await assert.rejects(svc.addStock('widget', 0), ValidationError);
  await assert.rejects(svc.reserve('o1', []), ValidationError);
});

test('unknown orders and bad order ids are rejected', async () => {
  const svc = await service();
  await assert.rejects(svc.commit('missing'), UnknownOrderError);
  await assert.rejects(svc.release('missing'), UnknownOrderError);
  await assert.rejects(svc.available('missing'), UnknownSkuError);
  await assert.rejects(svc.snapshot('missing'), UnknownSkuError);
  await assert.rejects(svc.reserve('  ', [{ sku: 'widget', qty: 1 }]), ValidationError);
  await assert.rejects(svc.commit(null), ValidationError);
  await assert.rejects(svc.release(''), ValidationError);
'use strict';

// Reproductions for INC-5521. Each describe block maps to one symptom in
// ISSUE.md. The store yields to the event loop on every call, so firing calls
// together with Promise.all interleaves them the way 40 checkout workers do.

const { describe, test } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  UnknownSkuError,
  UnknownOrderError,
  OrderStateError
} = require('../src');

// mulberry32: a seeded PRNG so a failing interleaving can be replayed.
function random(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

// Adds 0-3 extra event-loop turns before each call, so concurrent operations
// interleave in more orders than the fixed one-turn Store produces.
class JitterStore extends Store {
  constructor(seed) {
    super();
    this.rand = random(seed);
  }

  async jitter() {
    for (let turns = Math.floor(this.rand() * 4); turns > 0; turns--) {
      await tick();
    }
  }

  async get(key) {
    await this.jitter();
    return super.get(key);
  }

  async set(key, value) {
    await this.jitter();
    return super.set(key, value);
  }

  async keys(prefix) {
    await this.jitter();
    return super.keys(prefix);

