describe('mixed checkout workload', () => {
  test('40 workers reserving, retrying, committing, releasing, restocking and expiring keep every counter consistent', async () => {
    const rand = random(40);
    let t = 0;
    const skus = ['a', 'b', 'c', 'd', 'e'];
    const received = Object.fromEntries(skus.map(sku => [sku, 250]));
    const svc = await service(received, { now: () => t, reservationTtlMs: 1000 });
    const pick = () => skus[Math.floor(rand() * skus.length)];
    const settled = [];
    const workers = 40;
    const ordersPerWorker = 10;

    // The nightly job starts once half the orders are done, so it runs while
    // the other half are still reserving and committing.
    let processed = 0;
    let reachHalfway;
    const halfway = new Promise(resolve => { reachHalfway = resolve; });

    const worker = async w => {
      for (let n = 0; n < ordersPerWorker; n++) {
        const orderId = `w${w}-o${n}`;
        const items = [...new Set([pick(), pick(), pick()])].map(sku => ({ sku, qty: 1 + Math.floor(rand() * 3) }));
        const attempts = rand() < 0.3 ? 2 : 1;
        const reserves = await Promise.allSettled(Array.from({ length: attempts }, () => svc.reserve(orderId, items)));
        settled.push(...reserves);
        if (reserves[0].status === 'fulfilled') {
          const action = rand();
          if (action < 0.5) {
            settled.push(...(await Promise.allSettled([svc.commit(orderId), svc.commit(orderId)])));
          } else if (action < 0.8) {
            settled.push(...(await Promise.allSettled([svc.release(orderId), svc.commit(orderId)])));
          }
          // Otherwise the order is abandoned and left for expire().
        }
        processed += 1;
        if (processed === (workers * ordersPerWorker) / 2) reachHalfway();
      }
    };

    const restocker = async () => {
      for (let n = 0; n < 20; n++) {
        const sku = pick();
        await svc.addStock(sku, 1);
        received[sku] += 1;
      }
    };

    const nightlyExpire = async () => {
      await halfway;
      t = 5000;
      return svc.expire();
    };

    const [expired] = await Promise.all([
      nightlyExpire(),
      restocker(),
      ...Array.from({ length: workers }, (_, w) => worker(w))
    ]);

    assertRejectedOnlyWith(settled, InsufficientStockError, OrderStateError);
    const orders = await Promise.all((await svc.store.keys('order:')).map(key => svc.store.get(key)));
    assert.ok(expired.length > 0, 'expire should have found abandoned orders');
    assert.ok(orders.some(o => o.createdAt === 5000), 'workers should still be reserving while expire runs');
    assert.ok(orders.some(o => o.status === 'committed'));
    for (const orderId of expired) {
      assert.equal((await svc.store.get(`order:${orderId}`)).status, 'released', `${orderId} was expired`);
    }
    await assertLedger(svc, received);

